class Solution:
    def reverse(self, s: str, k: int) -> str:
        lst = list(s)
        i, j = 0, k - 1
        if j > len(s) - 1:
            j = len(s) - 1
        while i < j and j >= 0 and i < len(s):
            lst[i], lst[j] = lst[j], lst[i]
            i += 1
            j -= 1
        return "".join(lst)

    def reverseStr(self, s: str, k: int) -> str:
        chunks = []
        for i in range(0, len(s), 2 * k):
            chunks.append(s[i:i + 2*k])

        for i in range(len(chunks)):
            chunks[i] = self.reverse(chunks[i], k)

        ans = ""
        for chunk in chunks:
            ans += chunk

        return ans
